exec(open('build.py').read().split("# A rebuilt with wrapper")[0])
def W(inner,w,pad="0 40px 56px 0",extra=''):
    return f'<div class=wrap style="position:relative;display:inline-block;margin:50px 70px 90px 50px;width:{w}px">{inner}</div>'
def cardx(inner,style=''):
    return f'<div class=card style="border-radius:20px;{style}">{inner}</div>'
def float_(inner,style=''):
    return f'<div class=card style="position:absolute;border-radius:16px;box-shadow:0 2px 4px rgba(11,18,16,.05),0 30px 50px -14px rgba(11,18,16,.32);{style}">{inner}</div>'
def tile(n,s=44,bg='#E3F2EE'):
    return f'<span style="width:{s}px;height:{s}px;border-radius:12px;background:{bg};color:#0B1210;display:flex;align-items:center;justify-content:center;flex:none">{icon(n,int(s*.58))}</span>'
def chip(t,c='g',sz=13): return f'<span class="chip {c}" style="font-size:{sz}px;padding:5px 11px"><i></i>{t}</span>'
def bigfacts(a,b,c):
    f=lambda l,v:f'<div><div class=mono style="font-size:11px;margin-bottom:6px">{l}</div><div style="font-size:19px;font-weight:500">{v}</div></div>'
    return f'<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:12px;border-top:1px solid var(--line);padding-top:16px">{f("Minimum",a)}{f("Target raise",b)}{f("Term",c)}</div>'
# ---------- HERO 1 Home: one oversized deal card + peek + floating verification card
h1=W(f'''<div style="position:absolute;left:34px;top:30px;right:-34px;height:100%;border-radius:20px;background:rgba(255,255,255,.62);border:1px solid rgba(11,18,16,.05)"></div>
<div style="position:absolute;left:62px;top:60px;right:-62px;height:100%;border-radius:20px;background:rgba(255,255,255,.38);border:1px solid rgba(11,18,16,.04)"></div>
{cardx(f'<div style="padding:30px 32px 66px;display:flex;flex-direction:column;gap:16px"><div style="display:flex;justify-content:space-between;align-items:center"><span class=mono style="font-size:12px">Private equity</span>{chip("Open")}</div><div style="font-size:30px;font-weight:300;letter-spacing:-.02em;line-height:1.12">Northbridge Growth Partners III</div><div style="font-size:16px;color:var(--mut);line-height:1.5">Control and minority growth investments in mid-market business services across Europe.</div><div class=bar style="height:7px"><b style="width:64%"></b></div>{bigfacts("USD 250,000","USD 120m","8 years")}</div>','position:relative')}
{float_(f'<div style="display:flex;gap:14px;align-items:center;padding:16px 20px">{tile("verify",46)}<div><div style="font-size:16px;font-weight:500">Identity verified</div><div style="font-size:13.5px;color:var(--mut);margin-top:2px">Reused for every opportunity</div></div></div>','left:-34px;bottom:-46px;width:330px')}''',520)
open('H1.html','w').write(page(h1,900,760))
# ---------- HERO 2 Investors: oversized allocation + KPI + floating to-do
h2=W(f'''<div style="position:absolute;left:34px;top:30px;right:-34px;height:100%;border-radius:20px;background:rgba(255,255,255,.62);border:1px solid rgba(11,18,16,.05)"></div>
{cardx(f'<div style="padding:30px 32px 68px"><div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:22px"><div><div class=mono style="font-size:12px;margin-bottom:8px">Total commitments</div><div style="font-size:46px;font-weight:300;letter-spacing:-.03em;line-height:1">USD 1.05m</div></div>{chip("3 opportunities","d")}</div><div style="display:flex;align-items:center;gap:30px;border-top:1px solid var(--line);padding-top:22px">{donut([(24,"#0E6B5C"),(19,"#2FB89C"),(57,"#0F1F1D")],170,26)}<div style="display:flex;flex-direction:column;gap:16px;font-size:16px"><div style="display:flex;align-items:center;gap:12px"><i style="width:12px;height:12px;border-radius:3px;background:#0F1F1D"></i>Private credit</div><div style="display:flex;align-items:center;gap:12px"><i style="width:12px;height:12px;border-radius:3px;background:#0E6B5C"></i>Private equity</div><div style="display:flex;align-items:center;gap:12px"><i style="width:12px;height:12px;border-radius:3px;background:#2FB89C"></i>Real assets</div></div></div></div>','position:relative')}
{float_(f'<div style="display:flex;gap:14px;align-items:center;padding:16px 20px">{tile("sign",46,"#FBF1DC")}<div><div style="font-size:16px;font-weight:500">2 documents to sign</div><div style="font-size:13.5px;color:var(--mut);margin-top:2px">Northbridge Growth Partners III</div></div></div>','left:-34px;bottom:-46px;width:340px')}''',520)
open('H2.html','w').write(page(h2,900,760))
