def stat(n,l,hi=False):
    return f'<div style="border-top:3px solid {"var(--teal)" if hi else "var(--line)"};padding-top:14px"><div style="font-size:52px;font-weight:300;letter-spacing:-.03em;line-height:1">{n}</div><div style="font-size:14.5px;color:var(--mut);margin-top:8px">{l}</div></div>'
