# ---------- Section panels designed at real width
def panel_bg(w,h): return f'<div style="position:absolute;inset:0;{BG}"></div><svg style="position:absolute;inset:0" width={w} height={h} fill=none stroke="rgba(255,255,255,.10)" stroke-width=1.2><circle cx={w*.78} cy={h*.34} r={h*.5} /><circle cx={w*.62} cy={h*.34} r={h*.5} /></svg>'
BG='background:radial-gradient(900px 640px at 78% 8%,rgba(47,184,156,.34),transparent 60%),radial-gradient(800px 600px at 8% 100%,rgba(14,107,92,.30),transparent 62%),linear-gradient(180deg,#0A1514,#060C0B)'
def dcard(inner,x,y,w,z=1,style=''):
    return f'<div class=card style="position:absolute;left:{x}px;top:{y}px;width:{w}px;border-radius:20px;z-index:{z};box-shadow:0 40px 80px -20px rgba(0,0,0,.6);{style}">{inner}</div>'
def kp(l,v,s): return f'<div style="flex:1;padding:6px 0"><div class=mono style="font-size:11px;margin-bottom:10px">{l}</div><div style="font-size:38px;font-weight:300;letter-spacing:-.03em;line-height:1">{v}</div><div style="font-size:14px;color:var(--mut);margin-top:8px">{s}</div></div>'
def lrow(n,c,a,t,k): return f'<div style="display:grid;grid-template-columns:1.5fr 1fr 1fr auto;gap:12px;align-items:center;padding:14px 0;border-top:1px solid var(--line);font-size:16px"><span style="font-weight:500">{n}</span><span style="color:var(--mut)">{c}</span><span>{a}</span>{chip(t,k,13)}</div>'
GW,GH=1216,700
Gp=f'<div style="position:relative;width:{GW}px;height:{GH}px;overflow:hidden;{BG}">'+panel_bg(GW,GH)+dcard(f'<div style="padding:30px 34px 14px"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:20px"><div><div class=mono style="font-size:12px;margin-bottom:6px">Your investments</div><div style="font-size:34px;font-weight:300;letter-spacing:-.02em">Portfolio</div></div>{chip("3 opportunities","d")}</div><div style="display:flex;gap:30px;border-bottom:1px solid var(--line);padding-bottom:18px;margin-bottom:6px">{kp("Total commitments","USD 1.05m","Across 3 opportunities")}{kp("Open opportunities","6","2 closing this month")}{kp("Actions needed","2","Documents to sign")}</div>{lrow("Northbridge Growth Partners III","Private equity","USD 250,000","Committed","g")}{lrow("Solstice Solar Portfolio II","Real assets","USD 200,000","In review","a")}</div>',50,110,740,1)+dcard(f'<div style="padding:26px 28px"><div class=mono style="font-size:12px;margin-bottom:8px">Documents</div><div style="font-size:24px;font-weight:300;margin-bottom:16px">Subscription agreement</div><div style="border:1px solid var(--line);border-radius:12px;padding:16px 18px;margin-bottom:16px"><div class=mono style="font-size:11px;margin-bottom:8px">Electronic signature</div><div style="font-family:Georgia,serif;font-style:italic;font-size:34px;line-height:1.1">Alder Family Office</div></div><span class=btn style="width:100%;justify-content:center;font-size:15px;padding:13px">Confirm signature</span></div>',800,300,380,2)+'</div>'
open('G2.html','w').write(page(Gp,GW,GH,'#060C0B'))
def colx(t,n,rows,hi):
    return f'<div style="border-top:3px solid {"var(--teal)" if hi else "var(--line)"};padding-top:12px"><div style="display:flex;justify-content:space-between;margin-bottom:12px"><span style="font-size:17px;font-weight:500">{t}</span><span style="font-size:22px;font-weight:300">{n}</span></div>'+''.join(f'<div style="display:flex;align-items:center;gap:12px;border:1px solid var(--line);border-radius:12px;padding:11px 14px;margin-bottom:10px"><div class=av style="width:36px;height:36px">{r[0][0]}{r[0].split()[-1][0]}</div><div><div style="font-size:15px;font-weight:500">{r[0]}</div><div style="font-size:13px;color:var(--mut)">{r[1]}</div></div></div>' for r in rows)+'</div>'
Hp=f'<div style="position:relative;width:{GW}px;height:{GH}px;overflow:hidden;{BG}">'+panel_bg(GW,GH)+dcard(f'<div style="padding:30px 34px 18px"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:22px"><div><div class=mono style="font-size:12px;margin-bottom:6px">Raise overview</div><div style="font-size:32px;font-weight:300;letter-spacing:-.02em">Northbridge Growth Partners III</div></div><div style="display:flex;gap:10px">{chip("Open")}<span class=btn style="font-size:14px;padding:11px 16px">Share with advisers</span></div></div><div style="display:grid;grid-template-columns:repeat(3,1fr);gap:22px">{colx("Invited","48",[("Alder Family Office","Family office"),("Kestrel Partners","Investment firm")],False)}{colx("In review","17",[("Fenwick Capital","Investment firm"),("Blue Quay Advisory","Adviser-led")],False)}{colx("Committed","11",[("Sandhurst Trust","Foundation"),("Oakmere Holdings","Family office")],True)}</div></div>',40,80,800,1)+dcard(f'<div style="padding:24px 26px"><div class=mono style="font-size:12px;margin-bottom:8px">Investor view</div><div style="font-size:22px;font-weight:300;margin-bottom:14px">Opportunities</div><div style="font-size:19px;font-weight:400;margin-bottom:6px">Harbourline Senior Credit Fund</div><div style="font-size:14.5px;color:var(--mut);line-height:1.5;margin-bottom:14px">Senior secured loans to sponsor-backed mid-market borrowers.</div><div class=bar style="height:6px;margin-bottom:14px"><b style="width:41%"></b></div><div style="display:flex;justify-content:space-between;font-size:15px"><span>Minimum <b style="font-weight:500">USD 500,000</b></span>{chip("Open","g",12.5)}</div></div>',860,330,330,2)+'</div>'
open('H2p.html','w').write(page(Hp,GW,GH,'#060C0B'))
# ---------- Section panels on bg-alt at real width (1100): document and onboarding
def stepcol():
    return ''.join(f'<div style="display:flex;align-items:center;gap:14px;padding:13px 0;font-size:17px;{"font-weight:500;" if s=="Sign" else "color:var(--mut);" if s in ("Fund","Done") else ""}">{tile(i,44,"#E3F2EE" if s in ("Review","Sign") else "#F2F4F3")}{s}</div>' for s,i in (("Review","review"),("Sign","sign"),("Fund","fund"),("Done","verify")))
Dd=W(f'''<div style="position:absolute;left:30px;top:26px;right:-30px;height:100%;border-radius:20px;background:rgba(255,255,255,.62);border:1px solid rgba(11,18,16,.05)"></div>
{cardx(f'<div style="display:grid;grid-template-columns:1.5fr 1fr;gap:0"><div style="padding:34px 38px;border-right:1px solid var(--line)"><div class=mono style="font-size:12px;margin-bottom:10px">Northbridge Growth Partners III</div><div style="font-size:30px;font-weight:300;letter-spacing:-.02em;margin-bottom:18px">Subscription agreement</div><div style="display:grid;grid-template-columns:1fr 1fr;gap:16px;padding:16px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line);margin-bottom:18px"><div><div class=mono style="font-size:11px;margin-bottom:6px">Applicant</div><div style="font-size:17px">Alder Family Office</div></div><div><div class=mono style="font-size:11px;margin-bottom:6px">Commitment</div><div style="font-size:17px">USD 2,000,000</div></div></div><div style="font-size:15px;line-height:1.65;color:#33423E;margin-bottom:20px"><b style="font-weight:500">1. Subscription.</b> The Applicant subscribes for interests in the Fund in the amount stated above, subject to acceptance.</div><div style="border:1px solid var(--line);border-radius:12px;padding:16px 20px"><div class=mono style="font-size:11px;margin-bottom:8px">Electronic signature</div><div style="font-family:Georgia,serif;font-style:italic;font-size:38px;line-height:1.1">Alder Family Office</div></div></div><div style="padding:34px 32px;display:flex;flex-direction:column"><div class=mono style="font-size:12px;margin-bottom:8px">Progress</div>{stepcol()}<span class=btn style="margin-top:auto;justify-content:center;font-size:15px;padding:13px">Confirm signature</span></div></div>','position:relative')}''',1000)
